  const effects=`<section class="g8tradeeffects" aria-label="Estimated squad XI changes"><h3>Estimated squad XI changes</h3><div>${[['Batting',['powerplayBat','middleBat','finishing']],['Bowling',['newBall','middleBowl','death']],['Keeping',['keeping']]].map(([label,keys])=>{const a=Math.round(keys.reduce((n,k)=>n+before[k],0)/keys.length),b=Math.round(keys.reduce((n,k)=>n+after[k],0)/keys.length),delta=b-a;return `<div><span>${label}</span><strong class="${delta>0?'improved':delta<0?'declined':'steady'}">${delta>0?'+':''}${delta}</strong><small>${a} → ${b}</small></div>`}).join('')}</div><p>Your manual XI may differ. These are ability estimates, not predicted results.</p></section>`;
