 function scheduleReveal(){
  cancelReveal();const r=ui.reveal;if(!r||!r.running||r.count>=8||!revealActive())return;
  revealTimer=clock.setTimeout(()=>{revealTimer=null;if(!revealActive()||!ui.reveal.running)return;ui.reveal.count=Math.min(8,ui.reveal.count+1);ui.revealed=ui.reveal.count;if(ui.reveal.count===8)ui.reveal.running=false;render(false);save();scheduleReveal();},revealDelays[r.speedIndex]);
 }
 function startReveal(kind,snapshot=null){cancelReveal();ui.reveal={kind,count:snapshot?.count||0,speedIndex:snapshot?.speedIndex||0,running:snapshot?.running??true};ui.revealed=ui.reveal.count;scheduleReveal();}
 function finishReveal(){cancelReveal();ui.reveal=null;}
 bind('world',['story'],()=>{assert(ui.newCareer||!X.hasStoredSave(),'Another open game has started a career. Return home and choose Continue, or confirm Start again.');cancelMatchTimer();ui.match=null;finishReveal();read.fresh();ui.newCareer=false;G.skipLeagueReveal();ui.revealed=0;setView('leagueDraw');startReveal('league');render(false);save();});
 bind('revealClub',['leagueDraw'],()=>{assert(revealActive(),'Open the reveal first.');ui.reveal.count=Math.min(8,ui.reveal.count+1);ui.revealed=ui.reveal.count;if(ui.reveal.count===8)ui.reveal.running=false;scheduleReveal();});
 bind('revealAll',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive(),'Open the order reveal first.');cancelReveal();ui.reveal.count=8;ui.revealed=8;ui.reveal.running=false;});
 bind('revealRun',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive()&&ui.reveal.count<8,'The reveal is complete.');ui.reveal.running=!ui.reveal.running;scheduleReveal();});
 bind('revealSpeed',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive(),'Open the reveal first.');ui.reveal.speedIndex=(ui.reveal.speedIndex+1)%3;scheduleReveal();});
 bind('clubs',['leagueDraw'],()=>{assert(ui.reveal?.count===8,'Reveal the clubs first.');finishReveal();G.finishLeagueReveal();setView('clubs');});
 bind('club',['clubs'],i=>{assert(Number.isInteger(i)&&i>=0&&i<s.league.length,'Choose one of the eight clubs.');G.selectClub(i);const c=s.league[i];modal(c.name,X.clubBrief(c)+`<div class="g8actions g8clubconfirm">${btn('Take over this club','confirmClub',[],'g8primary')}</div>`,'club');});
 bind('confirmClub',['clubs'],()=>{assert(!s.userClub,'Your club has already been chosen.');assert(s.selectedClub!==null,'Choose a club.');G.confirmClub();setView('recruit');});
 bind('continue',['home'],()=>{assert(X.hasSave(),'There is no saved dynasty.');ui.draftShown=X.draftPageSize();if(!X.hasStoredSave()&&s.dynasty?.started){setView(views[ui.resumeView]?ui.resumeView:'team');announce('Continuing this session. This browser has not saved your progress.');return;}assert(D.resumeSave()===true,'The save could not be restored. Your saved data has been kept.');clock.resume();const savedReveal=s.dynasty.v8Reveal,view=X.screen();setView(view==='world'?'clubs':view);if(savedReveal&&savedReveal.year===s.year&&savedReveal.count<=8){if(savedReveal.kind==='league'){setView('leagueDraw');startReveal('league',savedReveal);}else if(savedReveal.kind==='draft'){window.GCC8_FOUNDATION_READ.pauseDraft();setView('draftDraw');startReveal('draft',savedReveal);}else if(savedReveal.kind==='annual'&&s.dynasty.offseason?.phase==='lottery'){setView('dynasty');startReveal('annual',savedReveal);}render(false);}else if(view==='dynasty'&&s.dynasty.offseason?.phase==='lottery'){startReveal('annual',{count:8,running:false});render(false);}const savedUI=s.dynasty.v8UI;if(savedUI){ui.teamReturn=savedUI.teamReturn;ui.seasonTab=savedUI.seasonTab;ui.result=s.results.find(r=>r.round===savedUI.resultRound)||null;archiveReturn=views[savedUI.archiveReturn]?savedUI.archiveReturn:'season';if(savedUI.view==='team'&&s.fullSchedule.length){G.go('team');setView('team');}else if(savedUI.view==='result'&&!savedUI.resultFinal){ui.result=s.results.find(r=>r.round===savedUI.resultRound);if(ui.result)setView('result');}else if(savedUI.view==='archive')setView('archive');render(false);}else if(view==='archive')archiveReturn=s.dynasty.careerClosed?'legacy':s.dynasty.offseason?'dynasty':s.dynasty.archiveReturnScreen||'season';cancelMatchTimer();ui.match=null;const savedMatch=s.dynasty.v8Match;if(savedMatch&&savedMatch.year===s.year){const r=matchFromReference(savedMatch.reference);if(r){ui.match={...savedMatch};ui.result=r;if(savedUI?.view==='matchReveal')beginMatch(r,savedMatch.returnView,savedMatch);}}if(annual())D.runCpuDraftUntilUser(false);});
 bind('breakawayStory','*',()=>modal('The breakaway story',`<article class="g8featurestory"><p class="g8storydateline">AN ALTERNATE CRICKET HISTORY · 2008</p><p class="g8storylede">One offer. Eight clubs. A new balance of power.</p><p>Twenty20 has changed the sound of cricket. Floodlights, packed stands and a match that can turn in an over. Now Saudi-backed investors want to change who runs it.</p><p>The proposal is bold: eight clubs, drawn from across the cricketing world, breaking from their domestic competitions to contest one global T20 league. They bring their colours, their grounds and their supporters. The playing lists are another matter.</p><section><h3>Five days to choose a side</h3><p>The established competitions still have their pull. So does the promise of a new stage. For five days, players decide whether to enter the breakaway. Proven internationals and emerging talent can put their names forward. Until the window closes, nobody knows quite how strong the field will be.</p></section><section><h3>Build an eleven worth watching</h3><p>Then comes the draft. Fifteen places in your squad. Seven rival clubs reading the same board. Do you take the opener who can win the powerplay, the quick who can defend twelve at the death, or the keeper your side still needs?</p><p>A famous name is only a start. Your ground, your balance and the eleven you send out will decide what follows.</p></section><section><h3>Make the years count</h3><p>Fourteen league matches lead to the finals. Beyond them, players develop, veterans retire and the next draft brings another judgement call. From the first ball in 2008 to the final season in 2026, the challenge is to build a club that lasts.</p></section><p class="g8storyclosing">The league has made its break. What will your club make of it?</p></article><div class="g8actions">${btn('Back to game','close',[],'g8primary')}</div>`,'breakawayStory'));
 bind('howItWorks','*',()=>modal('How it works',`<article class="g8featurestory"><p class="g8storydateline">INSIDE GLOBAL CHAMPIONS CRICKET</p><p class="g8storylede">You build the side. Cricket provides the uncertainty.</p><p>GCC is a cricket management simulation set in an alternate history. You shape a club through recruitment, selection and rebuilding. The match engine turns those decisions into deliveries, innings and seasons.</p><section><h3>A player is more than one number</h3><p>Overall ability gives you a quick starting point. Detailed skills and innings-phase ratings show where a player can contribute: taking on the new ball, building through the middle or finishing at the death. A high overall rating does not make every player equally suited to every job.</p><p>Read the role alongside the rating. A batting specialist, a part-time option and a frontline bowler offer different resources, even when their headline numbers look similar.</p></section><section><h3>Build a side, not a collection of stars</h3><p>Your fifteen-player squad provides options. Your selected XI and batting order decide who takes the field. Keeping, bowling coverage and players suited to different stages of an innings all matter when you put the side together.</p><p>Team and projected-XI ratings are useful summaries. They help you assess balance and quality; they are not predictions of a particular score or result.</p></section><section><h3>The ground changes the contest</h3><p>Pace, spin and boundary characteristics give grounds different demands. Match conditions add context. Consider those alongside your available players when choosing an XI, rather than assuming the same combination suits every fixture.</p></section><section><h3>Every innings has uncertainty</h3><p>Matches are simulated through individual deliveries. Player ability, the selected sides and the cricket situation influence the contest, with chance allowing for wickets, quiet spells and sudden boundaries. The stronger side has an advantage, not a guarantee.</p><p>Watching the ball-by-ball presentation helps you follow the innings. Speed and skip controls change how quickly you see the action, not your players’ ability. Use the scorebook to assess what happened across a match, and look for patterns across several games before judging a player.</p></section><section><h3>A career keeps moving</h3><p>Players develop and age as the seasons pass. Form and injuries affect the choices available to you. Development reports show changes, including individual skills that can move while overall ability stays level.</p><p>Scouting outlooks are judgements, not promises. Rival clubs also recruit and rebuild, so a successful squad will still need attention as careers progress.</p></section><p class="g8storyclosing">There is no guaranteed winning formula. Learn your squad, read the conditions and give your XI the best chance.</p></article><div class="g8actions">${btn('Back to game','close',[],'g8primary')}</div>`,'howItWorks'));
 bind('how','*',()=>modal('How to play','<p>Take over one of eight clubs. The five-day signing window decides which players enter the league. These are not signings for your club.</p><p>Build a fifteen-player squad in a fifteen-round snake draft. Scout names on the board and consider batting, bowling, keeping and your home ground.</p><p>Choose eleven manually. Move their batting order up or down, and swap players when form, injuries or conditions demand it. Ratings describe quality; results show whether your plans work.</p><p>Play fourteen league matches. The top four enter two semi-finals, followed by a Grand Final. Each offseason starts with a squad update. Players stay automatically unless they retire, are traded or you confirm an optional release. Trade only if it improves your side, then draft any vacant places and choose a fresh XI. There is no salary cap or wage management.</p><p>Tied scores are settled by a simplified Super Over: six legal balls or two wickets, repeated if tied. The model selects hitters and a bowler from each match XI. Tie-break figures are separate from season statistics.</p><p>Autosave keeps the career on this browser. The career ends after the 2026 season.</p>'));
