 bind('retainXI',['team'],()=>{assert(!s.xi.length&&!s.pendingSwapIn,'Clear the XI before restoring last season’s selection.');const previous=X.previousSelection();assert(previous.length,'No eligible players from last season’s XI.');for(const p of previous)G.toggleXI(p.id);s.battingOrder=previous.map(p=>p.id);s.orderTouched=true;ui.teamPane=s.xi.length===11?'xi':'squad';announce(s.xi.length===11?'Previous XI retained. Review the batting order and confirm.':`${s.xi.length} returning players selected. Fill the remaining places and confirm.`,true,true);});
 bind('reviewList',['dynasty'],()=>{const m=X.offseasonState();assert(m?.o.phase==='market','The list decisions are already confirmed.');modal('Ready for the draft draw?',`<p><b>${m.players.length} players stay with your club.</b> ${m.retired.length} retired${m.released.length?` and ${m.released.length} were released`:''}.</p><p>${m.vacancies?`You have ${m.vacancies} vacant ${m.vacancies===1?'place':'places'} to fill in the draft.`:'Your list is full. Watch the other clubs draft, then choose your opening XI.'}</p><p>Your remaining players stay. Optional releases close now; trades remain open until you enter the draft.</p><div class="g8actions">${btn('Confirm list · reveal order','annualDraw',[],'g8primary')}${btn('Back to my squad','close',[],'g8ghost')}</div>`,'listReview');});
 bind('annualDraw',['dynasty'],()=>{assert(s.dynasty.offseason?.phase==='market','The market is already closed.');if(!s.dynasty.offseason.cpuMarketRun)D.runCpuMarket();closeDialog();D.drawDraftOrder();startReveal('annual');});
 bind('annualDraft',['dynasty'],()=>{assert(s.dynasty.offseason?.phase==='lottery','Draw the order first.');assert(ui.reveal?.count===8,'Let the order reveal finish.');finishReveal();D.startAnnualDraft();resetFilters();});
