 bind('annualTeam',['dynasty','team'],()=>{if(ui.view==='team'){closeDialog();return;}assert(s.dynasty.offseason?.phase==='ready','Lodge the final list first.');D.enterTeamRoom();ui.teamReturn='season';setView('team');});
 bind('release',['dynasty'],id=>{assert(s.dynasty.offseason?.phase==='market'&&read.contractCandidates().includes(Number(id)),'That player cannot be released in this window.');const m=X.offseasonState();assert(m.remaining>0,'No optional releases remain this year.');const v=X.releaseImpact(id);ui.releaseId=Number(id);modal(`Release ${v.p.name}?`,`<p>Keeping this player needs no action. Releasing them returns them to the draft pool.</p><div class="g8consequences"><div><span>Your squad</span><strong>${v.before} → ${v.after}</strong></div><div><span>Places to draft</span><strong>${v.vacancies} → ${v.nextVacancies}</strong></div></div><p class="g8decisionwarning">${esc(v.warning)}</p><p>${v.remaining} optional ${v.remaining===1?'release':'releases'} would remain. Another club could draft this player. A confirmed release cannot be undone here.</p><div class="g8actions">${btn('Keep player','close',[],'g8primary')}${btn('Release '+v.p.name,'confirmRelease',[Number(id)],'g8danger')}</div>`,'release');});
 bind('confirmRelease',['dynasty'],id=>{assert(ui.modal==='release'&&ui.releaseId===Number(id)&&s.dynasty.offseason?.phase==='market'&&read.contractCandidates().includes(Number(id)),'Open this player’s release review first.');const budget=read.cutBudget(),o=s.dynasty.offseason;assert(o.voluntaryCuts.length+o.finalCuts.length<budget.limit,'No optional release remains.');D.releaseContractPlayer(Number(id));ui.releaseId=null;closeDialog();announce('Player released. The squad and draft places have been updated.');});
 bind('finalCut',['dynasty'],id=>{id=Number(id);assert(s.dynasty.offseason?.phase==='cuts'&&roster().length>15&&roster().some(p=>p.id===id),'Only an overfull list needs a final correction.');ui.releaseId=id;modal(`Release ${G.byId(id).name}?`,`<p>This older squad has ${roster().length} players. The limit is fifteen.</p><div class="g8consequences"><div><span>Your squad</span><strong>${roster().length} → ${roster().length-1}</strong></div><div><span>Still above fifteen</span><strong>${roster().length-15} → ${Math.max(0,roster().length-16)}</strong></div></div><p>The player returns to the draft pool. This corrects an oversized squad and does not open a new draft place.</p><div class="g8actions">${btn('Keep player','close',[],'g8primary')}${btn('Confirm release','confirmFinalCut',[id],'g8danger')}</div>`,'finalCut');});
 bind('confirmFinalCut',['dynasty'],id=>{id=Number(id);assert(ui.modal==='finalCut'&&ui.releaseId===id&&s.dynasty.offseason?.phase==='cuts'&&roster().length>15&&roster().some(p=>p.id===id),'Review this final-list release first.');const budget=read.cutBudget(),o=s.dynasty.offseason;assert(o.voluntaryCuts.length+o.finalCuts.length<budget.limit,'No optional release remains.');D.cutPlayer(id);ui.releaseId=null;closeDialog();});
 bind('trade',['dynasty','season'],trade);
 const tradeWindowOpen=()=>ui.tradeMid?s.round===7&&!s.dynasty.midseasonDone[s.year]:['market','lottery'].includes(s.dynasty?.offseason?.phase);
 bind('propose',['dynasty','season'],()=>{
  assert(ui.modal==='trade'&&tradeWindowOpen(),'Open an available trade window first.');assert(tradeValid(),'Choose both players before reviewing.');assert(!ui.tradePick||(!ui.tradeMid&&read.ownsPick(ui.tradePick)),'That draft pick is not available.');
  ui.tradeReview={club:ui.tradeClub,target:ui.tradeTarget,offer:ui.tradeOffer,pick:ui.tradePick,mid:ui.tradeMid};
  const off=G.byId(ui.tradeOffer),p=G.byId(ui.tradeTarget);modal('Review your trade',`<div class="g8exchangereview"><section><span class="g8eyebrow">YOU GIVE</span><h3>${esc(off.name)}</h3><p>${esc(X.roleLine(off))}</p>${ui.tradePick?`<b>Plus your round ${ui.tradePick==='R1'?1:2} draft pick</b>`:''}</section><span aria-hidden="true">⇄</span><section><span class="g8eyebrow">YOU RECEIVE</span><h3>${esc(p.name)}</h3><p>${esc(X.roleLine(p))}</p></section></div>${tradeImpact()}<p class="g8dialogcontext">${ui.tradeMid?'If accepted, review your XI before the next match.':'If accepted, these players change clubs immediately.'}</p><div class="g8actions">${btn('Confirm and send offer','confirmTrade',[],'g8primary')}${btn('Edit trade','editTrade',[],'g8ghost')}</div>`,'tradeReview');
 });
 bind('editTrade',['dynasty','season'],()=>{assert(['tradeReview','tradeResult'].includes(ui.modal),'There is no offer to edit.');assert(tradeWindowOpen(),'This trade window has closed.');ui.tradeReview=null;tradeDialog();});
 bind('confirmTrade',['dynasty','season'],()=>{
  const deal=ui.tradeReview;assert(ui.modal==='tradeReview'&&deal&&tradeWindowOpen(),'Review this trade before confirming.');assert(deal.club===ui.tradeClub&&deal.target===ui.tradeTarget&&deal.offer===ui.tradeOffer&&deal.pick===ui.tradePick&&deal.mid===ui.tradeMid&&tradeValid(),'The players changed. Review the trade again.');assert(!deal.pick||(!deal.mid&&read.ownsPick(deal.pick)),'That draft pick is no longer yours.');ui.tradeReview=null;
  D.openTradeCentre(deal.mid);document.getElementById('tradeClub').value=deal.club;D.refreshTradeTarget();document.getElementById('tradeTarget').value=String(deal.target);document.getElementById('tradeOffer').value=String(deal.offer);const pick=document.getElementById('tradePick');if(pick)pick.value=deal.pick;
  D.proposeTrade(deal.mid);const reply=document.getElementById('tradeRead').textContent,accepted=s.teams[own()].includes(deal.target);G.closeModal();
  modal(accepted?'Trade completed':'Offer declined',`<div id="g8tradeReply" class="g8notice" role="status">${esc(reply)}</div>${accepted?`<div class="g8consequences"><div><span>Joins your squad</span><strong>${esc(G.byId(deal.target).name)}</strong></div><div><span>Leaves your squad</span><strong>${esc(G.byId(deal.offer).name)}</strong></div></div>${deal.pick?`<p>Your round ${deal.pick==='R1'?1:2} pick now belongs to ${esc(X.clubName?X.clubName(deal.club):deal.club)}.</p>`:''}<p>${deal.mid?'Check your XI before the next match.':'Your updated squad is ready to review.'}</p><div class="g8actions">${btn('Back to my squad','close',[],'g8primary')}</div>`:`<p>No players or picks moved. You can change the package or keep your side.</p><div class="g8actions">${btn('Try another offer','editTrade',[],'g8primary')}${btn('Keep my squad','close',[],'g8ghost')}</div>`}`,accepted?'tradeComplete':'tradeResult');
 });
 bind('cover',['team'],id=>{const status=read.coverStatus(Number(id));assert(status.canSign&&status.owner===own(),'Choose a player who needs available injury cover.');const p=G.byId(status.originalId),options=read.replacements(p.id);assert(options.length,'No suitable fit replacement is available.');ui.coverId=p.id;modal(status.currentCoverId?`Replace cover for ${p.name}`:`Cover ${p.name}`,`<p>${status.currentCoverId?`${esc(status.coverName)} is unavailable. The new replacement takes over this cover spell.`:'Choose a fit temporary replacement.'} They stay until ${esc(p.name)} is cleared to play. Selection in the XI remains your decision.</p><div class="g8board">${options.slice(0,18).map(G.byId).map(p=>playerCard(p,'signCover','Sign as cover')).join('')}</div>`,'cover');});
 bind('signCover',['team'],id=>{assert(ui.modal==='cover'&&read.replacements(ui.coverId).includes(Number(id)),'Choose an eligible replacement.');const status=read.coverStatus(ui.coverId);assert(status.canSign&&status.owner===own(),'That cover spell no longer needs a replacement.');D.signReplacement(ui.coverId,Number(id));assert(s.dynasty.replacementFor[ui.coverId]===Number(id),'The replacement could not be signed.');closeDialog();announce('Injury cover signed. Choose whether to put them in your XI.');});
 bind('archive','*',()=>{assert(s.dynasty?.history?.length,'The archive opens after your first completed season.');archiveReturn=ui.view==='archive'?archiveReturn:ui.view;D.openArchive();setView('archive');});
 bind('archiveBack',['archive'],()=>{D.backFromArchive();setView(views[archiveReturn]?archiveReturn:X.screen());});
 bind('archiveSeason',['archive'],year=>{const h=s.dynasty.history.find(h=>h.year===Number(year));assert(h,'That season is not in the archive.');const stats=Object.entries(h.userPlayerStats||{}).sort((a,b)=>b[1].runs-a[1].runs);modal(`${year} · The club scorebook`,`<p>${h.wins} wins · ${h.losses} losses · Finished ${h.userPosition}</p><div class="g8tablewrap"><table class="g8table"><thead><tr><th>Player</th><th>Matches</th><th>Runs</th><th>Wickets</th></tr></thead><tbody>${stats.map(([id,t])=>`<tr><td>${esc(G.byId(Number(id))?.name||id)}</td><td>${t.matches||0}</td><td>${t.runs||0}</td><td>${t.wickets||0}</td></tr>`).join('')}</tbody></table></div>`);});
 X.dispatch=(action,args=[])=>{
  if(busy)return false;if(!Array.isArray(args)){announce('Invalid command arguments.');return false;}
  const fn=commands[action];if(!fn){announce('That control is unavailable.');return false;}
  const where=allow[action];if(where!=='*'&&!where.includes(ui.view)){announce('That action belongs to a different stage of the career.');return false;}
  closeUtilityMenu();busy=true;const view=ui.view,x=window.scrollX,y=window.scrollY;
  try{clearFeedback();fn(...args);completeDraft();save();if(ui.view===view&&!ui.modal)render(false);return true;}
  catch(e){announce(e.message||'The action could not be completed.');return false;}
  finally{G.closeModal();busy=false;if(pendingFocus){const target=document.querySelector(pendingFocus);pendingFocus=null;target?.focus?.({preventScroll:true});target?.scrollIntoView?.({block:'center',behavior:'instant'});}else if(ui.view===view)window.scrollTo({left:x,top:y,behavior:'instant'});}
 };
 document.addEventListener('click',event=>{if(!event.target.closest?.('.g8utilitymenu'))closeUtilityMenu();});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&hud.querySelector('.g8utilitymenu[open]')){closeUtilityMenu(true);event.preventDefault();}});
 document.getElementById('g8app').addEventListener('click',event=>{let b=event.target.closest?.('button[data-action]');if(!b){const card=event.target.closest?.('.g8directpick');if(card&&!event.target.closest('.g8candidatechoice'))b=card.querySelector('.g8candidate');}if(!b||b.disabled)return;if(b.matches('.g8candidate'))b.focus({preventScroll:true});X.dispatch(b.dataset.action,JSON.parse(b.dataset.args||'[]'));});
 document.getElementById('g8app').addEventListener('input',event=>{
  const el=event.target,key=el.dataset?.input;if(!key)return;
  if(key==='search'&&['draft','dynasty'].includes(ui.view)){ui.search=el.value;ui.draftShown=X.draftPageSize();const board=document.getElementById('g8pool');X.patch(board,X.poolBoard(annual()));}
 });
 document.getElementById('g8app').addEventListener('change',event=>{
  const el=event.target,key=el.dataset?.input;if(key==='squadFilter'){X.dispatch('squadFilter',[el.value]);document.getElementById('g8squadrole')?.focus({preventScroll:true});return;}if(key==='compareTarget'&&ui.modal==='compare'){X.dispatch('comparePlayers',[ui.comparePlayer,Number(el.value)]);content.querySelector('[data-input="compareTarget"]')?.focus({preventScroll:true});return;}if(['filter','sort'].includes(key)&&['draft','dynasty'].includes(ui.view)){ui[key]=el.value;ui.draftShown=X.draftPageSize();X.patch(document.getElementById('g8pool'),X.poolBoard(annual()));}
  if(['tradeClub','tradeTarget','tradeOffer','tradePick'].includes(key)&&ui.modal==='trade'){
   if(key==='tradeClub'){if(!s.league.some(c=>c.abbr===el.value&&c.abbr!==own()))return;ui.tradeClub=el.value;ui.tradeTarget=null;}
   else if(key==='tradePick'){if(el.value&&(!['R1','R2'].includes(el.value)||ui.tradeMid||!read.ownsPick(el.value)))return;ui.tradePick=el.value;}
   else{const id=Number(el.value),ids=key==='tradeOffer'?s.teams[own()]:s.teams[ui.tradeClub];if(el.value&&(!ids?.includes(id)||G.byId(id)?.dynastyReplacement))return;ui[key]=el.value?id:null;}
   ui.tradeReview=null;tradeDialog();content.querySelector(`[data-input="${key}"]`)?.focus({preventScroll:true});
  }
 });
 dialog.addEventListener('cancel',event=>{event.preventDefault();X.dispatch('close');});
 window.addEventListener('resize',()=>X.accessibleTables(dialog.open?content:stage));
 window.addEventListener('pagehide',()=>{clock.pause();G.pauseSeason();save();});
 window.addEventListener('pageshow',()=>{if(!document.hidden&&!ui.modal&&!['home','story'].includes(ui.view))clock.resume();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){clock.pause();save();}else if(!ui.modal&&!['home','story'].includes(ui.view))clock.resume();});
 X.render=render;X.commands=Object.freeze(Object.keys(commands));X.showScorecard=scorecard;
